DROP TABLE IF EXISTS `auditoria`;

CREATE TABLE `auditoria` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `fecha` datetime DEFAULT current_timestamp(),
  `producto` varchar(255) DEFAULT NULL,
  `mascota` varchar(255) DEFAULT NULL,
  `categoria` varchar(100) DEFAULT NULL,
  `servicio` varchar(255) DEFAULT NULL,
  `accion` varchar(50) NOT NULL,
  `responsable` varchar(100) DEFAULT NULL,
  `modulo` enum('productos','estetica','clientes','mascotas','caja','turnos','historial','empleados','otros') DEFAULT 'productos',
  `id_referencia` int(11) DEFAULT NULL,
  `precio_venta` decimal(10,2) DEFAULT NULL,
  `stock` int(11) DEFAULT NULL,
  `eliminado` tinyint(1) DEFAULT 0,
  `usuario_modificacion` varchar(100) DEFAULT NULL,
  `fecha_modificacion` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_fecha` (`fecha`),
  KEY `idx_modulo` (`modulo`)
) ENGINE=InnoDB AUTO_INCREMENT=607 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


LOCK TABLES `auditoria` WRITE;
;
