DROP TABLE IF EXISTS `estetica`;

CREATE TABLE `estetica` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `turno_id` int(11) NOT NULL,
  `tipo_servicio` varchar(100) NOT NULL,
  `realizado` tinyint(1) DEFAULT 0,
  `observaciones` text DEFAULT NULL,
  `comportamiento` varchar(50) DEFAULT NULL,
  `peso_final` varchar(20) DEFAULT NULL,
  `creado_por` int(11) DEFAULT NULL,
  `creado_en` datetime DEFAULT current_timestamp(),
  `editado_por` int(11) DEFAULT NULL,
  `editado_en` datetime DEFAULT NULL,
  `atendido_por` int(11) DEFAULT NULL,
  `atendido_en` datetime DEFAULT NULL,
  `eliminado_por` int(11) DEFAULT NULL,
  `eliminado_en` datetime DEFAULT NULL,
  `finalizado_por` int(11) DEFAULT NULL,
  `finalizado_en` datetime DEFAULT NULL,
  `fecha_borrado` datetime DEFAULT NULL,
  `borrado_por` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `turno_id` (`turno_id`),
  CONSTRAINT `estetica_ibfk_1` FOREIGN KEY (`turno_id`) REFERENCES `turnos` (`id`) ON DELETE CASCADE
