DROP TABLE IF EXISTS `turnos`;

CREATE TABLE `turnos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `mascota_id` int(11) DEFAULT NULL,
  `dueno_id` int(11) DEFAULT NULL,
  `veterinario_id` int(11) DEFAULT NULL,
  `fecha` datetime NOT NULL,
  `tipo` enum('consulta','vacunacion','estetica','cirugia','urgencia','control') NOT NULL,
  `estado` enum('pendiente','confirmado','cancelado','realizado') DEFAULT 'pendiente',
  `motivo` text DEFAULT NULL,
  `es_urgencia` tinyint(1) DEFAULT 0,
  `fecha_borrado` datetime DEFAULT NULL,
  `borrado_por` int(11) DEFAULT NULL,
  `duracion` int(11) DEFAULT 15,
  PRIMARY KEY (`id`),
  KEY `mascota_id` (`mascota_id`),
  KEY `dueno_id` (`dueno_id`),
  KEY `veterinario_id` (`veterinario_id`),
  CONSTRAINT `turnos_ibfk_1` FOREIGN KEY (`mascota_id`) REFERENCES `mascotas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `turnos_ibfk_2` FOREIGN KEY (`dueno_id`) REFERENCES `duenos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `turnos_ibfk_3` FOREIGN KEY (`veterinario_id`) REFERENCES `empleados` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=158 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

